import{readdir,copyFile,stat}from'node:fs/promises';
const inventory=[];const hits=[];
const terms={outfit:['function m({children:','let i=["/preloader','duration:3,innerText','leave:e=>','enter:e=>','["Item",','FirstRowItemsReveal','GridItemsScroll','function i(){let e=','grid-cols-2 gap-4 lg:grid-cols-4'],kvs:['Bk={models:','De={color:','function Ve()','function He()','function Ke(','function at()','function ft()','new Ak({antialias:'],avara:['background:#000','duration:1.7','uFalloff','fog']};
for(const n of ['outfit','avara','kvs'])for(const f of await readdir(`research/references/${n}`,{recursive:true})){const path=`research/references/${n}/${f}`;if(!(await stat(path)).isFile())continue;const file=Bun.file(path);if(!file.size||f.endsWith('json'))continue;let body: string|undefined; if(/\.(js|css|html)$/.test(f))body=await file.text();inventory.push({path,bytes:file.size,sha256:new Bun.CryptoHasher('sha256').update(await file.arrayBuffer()).digest('hex'),type:body&&/^\s*<!?\w/.test(body)?'HTML':f.split('.').pop(),sourceMap:body?.includes('sourceMappingURL=')??false});if(body)for(const term of terms[n]){const at=body.indexOf(term);if(at>=0)hits.push({site:n,path,offsetCharacters:at,term,context:body.slice(Math.max(0,at-100),at+1600)});}}
await copyFile('/dev/shm/codex-clipboard-XjiHMl.png','research/references/grid-reference.png');
const model=await Bun.file('research/references/kvs/kvsB.glb').arrayBuffer();const dv=new DataView(model);const len=dv.getUint32(12,true);const gltf=JSON.parse(new TextDecoder().decode(model.slice(20,20+len)));await Bun.write('research/references/kvs/model-inspection.json',JSON.stringify({magic:dv.getUint32(0,true),version:dv.getUint32(4,true),declaredBytes:dv.getUint32(8,true),actualBytes:model.byteLength,asset:gltf.asset,nodes:gltf.nodes?.map(n=>({name:n.name,mesh:n.mesh})),meshes:gltf.meshes?.length,extensionsUsed:gltf.extensionsUsed},null,2));
await Bun.write('research/references/inventory.json',JSON.stringify(inventory,null,2));await Bun.write('research/references/evidence.json',JSON.stringify(hits,null,2));console.log({files:inventory.length,bytes:inventory.reduce((a,x)=>a+x.bytes,0),evidence:hits.length,htmlDisguisedAsJs:inventory.filter(x=>x.type==='HTML'&&x.path.endsWith('.js')).map(x=>x.path),sourceMaps:inventory.filter(x=>x.sourceMap).map(x=>x.path),modelMeshes:gltf.meshes?.length,modelNodes:gltf.nodes?.length});
